\label{rem:nachbin-separation}
Compact ordered spaces are Hausdorff, since they are normally ordered \cite[I.2]{NachbinTopologyAndOrder}, that is, they satisfy \textbf{Nachbin separation}
\begin{equation}\label{eq:nachbin-separation}
\begin{gathered}
D \text{ closed down-set},\;
U \text{ closed up-set},\;
D\cap U=\emptyset
\\[0.3em]
\Longrightarrow\quad
\exists\, d\text{ lower open},
\exists\, u\text{ upper open}\text{ such that } \;
D\subseteq d,\;
U\subseteq u,\;
d\cap u=\emptyset.
\end{gathered}
\end{equation}
Synonyms for compact ordered space include compact order-Hausdorff space \cite[VII.2.1]{JohnstoneStoneSpaces}, compact pospace \cite[9.1]{Goubault-LarrecqNonHausdorff}, and Nachbin space.

\label{rem:dual-properties-relations}
A useful consequence of the order on relations is that it allows us to express how some important properties dualise: duality reverses the order between relations, so we have the following dual properties of relations $R: C\looparrowright C$:
\begin{itemize}
  \item \textbf{above identity} (${\le_C} \subseteq R$, reflexive) $\longleftrightarrow$ \textbf{below identity} ($R \subseteq {\le_C}$).
  \item \textbf{transitive} ($R\,;R \subseteq R$) $\longleftrightarrow$ \textbf{interpolative} ($R \subseteq R\,; R$).
  \item \textbf{monad} (idempotent above identity, closure operator) $\longleftrightarrow$ \textbf{comonad} (idempotent below identity, interior operator).
\end{itemize}
Hence a Priestley preorder (reflexive, transitive) corresponds dually to a proximity relation (interpolative below identity). Equivalently, preorders are idempotent relations above identity and proximity relations are idempotent relations below identity.

\label{rem:ba-prox-equiv}
Recall that the dual $R$ of a closed relation $S$ on a Stone space is a $\mathsf{DL}$-relation on a Boolean algebra.
\begin{itemize}
  \item $S$ is \textbf{symmetric} iff $aRb \Leftrightarrow\neg b R\neg a$, 
\end{itemize}
see also (S6) in \cite[Lem.~4.6]{BBSV17}.
Thus a Boolean proximity dualises to an equivalence relation precisely when this self-duality holds. The Cantor space proximity in Section~\ref{sec:cantor} is of that kind.

\label{def:double-category}
A (strict) \textbf{double category} $\mathbb C$ is a category internal to the category of categories

\[\begin{tikzcd}
\mathbb C_1 \arrow[r, shift left, "\mathrm{dom}"] \arrow[r, shift right, "\mathrm{cod}" swap] & \mathbb C_0
\end{tikzcd}\]

\label{def:dgf}
A \textbf{descriptive general frame} ($\mathsf{DGF}$) $(X,R)$ is a Stone space with a closed relation $R$ such that $R^{-1}$ preserves clopens. 

The inverse image of $R$ preserves clopens iff, for any clopen $b$, the set $\{a\mid a\prec b\}$ has a maximal element (given by $\Box_R b$). Such a relation $\prec$ is called \textbf{modally definable}, see \cite[Def 2.9, Lem 4.3]{BBSV17}.

\label{def:splitting-idempotents}
Let $\mathbb C$ be a flat double category.
The double category ${\mathbb S}\mathsf{pl}_\le(\mathbb C)$ is defined by the following data.
\begin{itemize}
\item Objects $(C,R)$ where $C$ is an object of $\mathbb C$ and $R:C\looparrowright C$ is an idempotent proarrow in $\mathbb C$ below the identity ($R\le\mathrm{Id}_C$). 
\item Arrows $f:(C,R)\to(C',R')$ where $f$ is an arrow of $\mathbb C$ such that $(f,f):R\looparrowright R'$ is a square in $\mathbb C$, that is, $cRd\Rightarrow f(c) R' f(d)$.
\item Proarrows $S:(C,R)\looparrowright(C',R')$ where $S:C\looparrowright C'$ in $\mathbb C$ with $R \mathrel{;} S \mathrel{;} R' \,=\, S$. The identity proarrow on $(C,R)$ is $R$.
\item Squares $(f,g):S\looparrowright S'$ where $(f,g):S\looparrowright S'$ is a square in $\mathbb C$, that is, $cSd \Rightarrow f(c) S' g(d)$.
\end{itemize}
${\mathbb S}\mathsf{pl}_\ge(\mathbb C)$ is defined analogously but with respect to idempotents above the identity ($R\ge\mathrm{Id}_C$).

We note the following.
\begin{itemize}
\item An idempotent proarrow above (below) the identity is a monad (comonad) in the $\mathsf{Pos}$-category of relations.
\item Splitting idempotents preserves equivalence of double categories.
\item ${\mathbb S}\mathsf{pl}_\ge(\mathbb C)=({\mathbb S}\mathsf{pl}_\le(\mathbb C^\mathrm{op}))^\mathrm{op}$ (on the proarrow projection this is the $^\mathrm{co}$ of Theorem~\ref{thm:duality-for-relations}).
\end{itemize}

\label{thm:spl-pri-dl}
There is an equivalence of double categories
\[
    {\mathbb S}\mathsf{pl}_\ge({\mathbb R}\mathsf{el}(\mathsf{Pri})) \simeq {\mathbb S}\mathsf{pl}_\le({\mathbb R}\mathsf{el}(\mathsf{DL}))^\mathrm{op}
\]
that extends the classical Priestley duality.

\label{rem:prox-axioms}
The conditions on a proximity relation $\prec$ are equivalent to the following:
  $$\prec\circ\prec {=} \prec \quad\quad {\prec}\subseteq\ \le$$ 

  \begin{gather*}
  \frac{a\le b \quad\quad b\prec c \quad\quad c\le d}{a\prec d}
  \end{gather*}


  \begin{gather*}
  0 \prec 0 \quad\quad 1\prec 1 \\[0.7em]
  \frac{a \prec b \quad\quad c\prec d}{a \vee c \, \prec \, b\vee d} \quad\quad \frac{a   \prec b \quad\quad c\prec d}{a \wedge c \, \prec \, b \wedge d}
   \end{gather*}
Similarly, the conditions on a relation (proarrow) $R:(A,\prec)\looparrowright(A',\prec')$ are equivalent to the following:
   \begin{gather*}
    \frac{a_1\le a_2 \quad\quad a_2 R\,  a_1' \quad\quad a_1'\le a_2'}{a_1 R\,  a_2'} \\[0.7em]
 0 R 0' \quad\quad 1 R 1' \\[0.7em]
  \frac{a R b \quad\quad cR d}{(a \vee c) \, R \, (b\vee d)} \quad\quad \frac{a   R b \quad\quad cR d}{(a \wedge c) \, R \, (b\wedge d)}\\[0.7em]
    \frac{a_1\prec a_2 \quad\quad a_2 R\, a_1' \quad\quad a_1'\prec a_2'}{a_1 R\, a_2'}   \end{gather*}

\label{rem:prox-simplified-axioms}
Given that $\prec$ is a weakening relation below identity on the underlying poset of a $\mathsf{DL}$, it is enough to check
   \begin{gather*}
   a\prec c \ \textrm{ only if there is $b$ such that } \ a\prec b \ \textrm{ and } \ b\prec c  \\[0.7em]
   \frac{a \prec b \quad\quad b\prec c}{a \prec c}  \\[0.7em]
  0 \prec 0 \quad\quad 1\prec 1 \\[0.7em]
  \frac{a \prec b \quad\quad c\prec b}{a \vee c  \prec \, b} \quad\quad \frac{a   \prec b \quad\quad a\prec d}{a  \prec b \, \wedge d}
   \end{gather*}
in order to obtain a proximity lattice.
In particular, one derives the full rules for conjunction and disjunction of Remark~\ref{rem:prox-axioms} by weakening. Conversely, the last two rules above follow from those of Remark~\ref{rem:prox-axioms} using that in a $\mathsf{DL}$ we have $b\vee b=b$ and $a\wedge a = a$. The conditions on $R$ for $\wedge$ and $\vee$ can be simplified in an analogous way.

Moreover, since we know that $\prec$ and $\prec'$ are idempotent, the condition ${\prec} \mathrel{;} R \mathrel{;} {\prec'} \,=\, R$ is equivalent to ${\prec} \mathrel{;} R \,=\, R$ and $R \mathrel{;} {\prec'} \,=\, R$.

\begin{itemize}
  \item Henceforth, we will take ${\mathbb P}\mathsf{rox} = {\mathbb S}\mathsf{pl}_\le({\mathbb R}\mathsf{el}(\mathsf{DL}))$ as the definition of (the double category of) proximity lattices. The categories $\mathsf{Prox}$ (proximity lattices with functional arrows) and $\mathsf{ProxRel}$ (proximity lattices with relational arrows) then arise as the arrow, respectively proarrow, projections of ${\mathbb P}\mathsf{rox}$.
  \item While $\mathsf{ProxRel}$ is the proarrow projection of ${\mathbb P}\mathsf{rox}$, it is not $\mathsf{Rel}(\mathsf{Prox})$. The natural forgetful functor $\mathsf{Prox}\to\mathsf{Pos}$ sends $(A,\prec)$ to $(A,\le)$, since $\prec$ need not be reflexive, so identities in $\mathsf{Rel}(\mathsf{Prox})$ are lattice orders, whereas identities in $\mathsf{ProxRel}$ are the proximities $\prec$.
  \item Going back to Section~\ref{sec:dualities-relations}, $\mathsf{Prox}$ is the full subcategory of $\mathsf{SubDL}$ consisting of the subordination algebras where the subordination is idempotent and below identity. 
\end{itemize}

\label{def:kohaus-proximity-lattice}
The proximity lattice $(A, \prec)$ is \textbf{the proximity lattice of a compact ordered space} $X$ if
   \begin{itemize}
     \item $A$ is the set of pairs $(d, u)$ where $d$ is a lower open set and $u$ is an upper open set and $d \cap u = \emptyset$;
     \item $(d, u) \le (d', u')$ if and only if $d \subseteq d'$ and $u \supseteq u'$.
     \item $(d, u) \prec (d', u')$ if and only if $u \cup d'$ covers $X$, ie, $u \cup d' = X$.
   \end{itemize}

\label{prop:gentzen-cut}
  If $(A,\prec)$ is $\vee$-strong or $\wedge$-strong, then it satisfies the Gentzen cut rule
  \begin{gather*}
  \frac{a\prec b\vee c \quad\quad a\wedge c\prec b}{a\prec b}.
  \end{gather*}

\label{def:priestley-preorder}
  A \textbf{Priestley preorder} $(X, \sqsubseteq)$ is a Priestley space $X$ with an idempotent $\mathsf{Pri}$-relation $\sqsubseteq$ above the identity. The category $\mathsf{PriPre}$ of Priestley preorders has arrows $f:(X,\sqsubseteq)\to(X',\sqsubseteq')$ which are continuous monotone functions preserving the preorder: $x \sqsubseteq y\ \Rightarrow \ f(x) \sqsubseteq' f(y)$.
  The double category ${\mathbb P}\mathsf{riPre}$ has proarrows $S:(X,\sqsubseteq)\looparrowright(X',\sqsubseteq')$ such that $S:X\looparrowright X'$ is a $\mathsf{Pri}$-relation and ${\sqsubseteq} \mathrel{;} S \mathrel{;} {\sqsubseteq'} \,=\, S$.

\label{prop:quotient-to-kohaus}
  The quotient construction of Definition~\ref{def:quotient-functor} defines a functor
  \[
    \mathsf{PriPre} \to \mathsf{KOHaus}
  \]
  from the category of Priestley preorders to the category of compact ordered spaces. In particular, every quotient of a Priestley preorder is a compact ordered space.

\label{prop:pointsarecuts}
In the situation of Diagram \eqref{eq:adjointrelsinpos} take $B=\mathbbm{2}=\{0<1\}$ and let ${\ll}={\le}$. Then $(L0,1R)$ is a \textbf{cut} in the sense that 
\begin{itemize}
\item $L0$ is a downset and $1R$ is an upset 
\item (roundness) $\forall a\in L0\,.\,\exists a'\in L0\,.\,a\prec a'$ and $\forall a\in 1R\,.\,\exists a'\in 1R\,.\,a'\prec a$
\item (disjointness) $L0\cap 1R=\emptyset$ 
\item (tightness) If $a\prec a'$ then $a\in L0 \textrm{ or } a'\in 1R$ 
\end{itemize}
and every cut is of this form for a unique pair $L\dashv R$.
If, moreover, $A$ is a lattice and $L,R$ are lattice relations, then $L0$ is an ideal and $1R$ is a filter.

\label{prop:prime-cut-theorem}
  In a strong proximity lattice $(A,\prec)$, if $I:A\looparrowright \mathbbm{2}$ and $F:\mathbbm{2}\looparrowright A$
  satisfy $F \mathrel{;} I \, \subseteq \, \mathord{\le}$, then there is an adjoint pair $(I^*,F^*):A\looparrowright \mathbbm{2}$ so that $I\subseteq I^*$ and $F\subseteq F^*$.

\label{rem:cuts-vs-prime-cuts}
The distinction between a general cut and a \textbf{prime cut} (ie, a round prime filter) arises from the type of adjoint pair $L\dashv R$ used to define them:
\begin{itemize}
\item General cuts arise from adjoint pairs $L\dashv R:(A,\prec)\to(\mathbbm{2},\le)$ of weakening relations. These give a notion of point analogous to Dedekind cuts: a partition of $A$ into a round lower part $L0$ and a round upper part $1R$ satisfying disjointness and tightness.
\item Prime cuts arise when $A$ is a strong proximity lattice and $L$ and $R$ are $\mathsf{DL}$-relations, see Proposition~\ref{prop:round-prime}.
\end{itemize}
For Stone and Priestley duality, points are given by $\mathsf{DL}$-morphisms $A\to\mathbbm{2}$. For compact ordered spaces, points are given by left-adjoint $\mathsf{ProxRel}$-relations $(A,\prec)\looparrowright\mathbbm{2}$.

\label{def:filt-rfilt-rpfilt}
For a lattice $A$, we denote by $\mathsf{Filt}(A)$ the lattice of filters of $A$.
For a proximity lattice $A$, we write $\mathsf{RFilt}(A)$ for the lattice of round filters and $\mathsf{RPFilt}(A)$ for the set of round prime filters.

Since ${\equiv} \,=\, {\sqsubseteq} \cap{\sqsupseteq}$ and the inverse of a closed relation is closed, it suffices to show that $\sqsubseteq$ is closed. We show that the complement of $\sqsubseteq$ is open:
\begin{align*}
\{(F, F') \mid F \not\sqsubseteq F'\} &= \{(F, F') \mid \exists a, a'\in A.\, a \prec a' \,\&\, a \in F \,\&\, a' \notin F'\} \\
&= \bigcup_{a \prec a'} \bigl(\{F \mid a \in F\} \times \{F' \mid a' \notin F'\}\bigr)
\end{align*}
Each set $\{F \mid a \in F\} \times \{F' \mid a' \notin F'\}$ is open in the product of Priestley topologies (as a product of basic opens). Hence the complement of $\sqsubseteq$ is a union of opens, so $\sqsubseteq$ is closed.

\label{def:map-spl-pri}
  The order-enriched category $\mathsf{Map}({\mathbb S}\mathsf{pl}_\ge({\mathbb R}\mathsf{el}(\mathsf{Pri})))$ has objects Priestley preorders $(X,\sqsubseteq_X)$, $(Y,\sqsubseteq_Y)$, etc., and arrows $(X,\sqsubseteq_X) \to (Y,\sqsubseteq_Y)$ that are left-adjoint relations (proarrows) in ${\mathbb S}\mathsf{pl}_\ge({\mathbb R}\mathsf{el}(\mathsf{Pri}))$. Relations are ordered by inclusion.
  In general, if $\mathbb{C}$ is a double category of relations, $\mathsf{Map}(\mathbb{C})$ denotes the order-enriched category of \emph{maps} in $\mathbb{C}$: its arrows are the left-adjoint proarrows of $\mathbb{C}$.

We spell out the conditions on an arrow $L:(X,\sqsubseteq_X) \to (Y,\sqsubseteq_Y)$ in $\mathsf{Map}({\mathbb S}\mathsf{pl}_\ge({\mathbb R}\mathsf{el}(\mathsf{Pri})))$. 
  \begin{enumerate}
    \item Weakening with respect to identities: ${\le_X} \mathrel{;} L \mathrel{;} {\le_Y} = L$.
    \item Priestley relation: $L$ is a closed subspace of $X \times Y$.
    \item Weakening with respect to idempotents: ${\sqsubseteq_X} \mathrel{;} L \mathrel{;} {\sqsubseteq_Y} \,=\, L$.
    \item \textbf{$L$ has a right adjoint} $R \subseteq Y \times X$ satisfying the laws 1--3 above as well as the adjunction laws: for all $x,x' \in X$ and $y,y' \in Y$,
    \begin{align*}
      x \sqsubseteq_X x' \ &\Rightarrow \ \exists y \in Y.\, x \, L \, y \ \wedge \ y \, R \, x' & \text{(Unit)}\\
      \exists x \in X.\, y \, R \, x \, L \, y' \ &\Rightarrow \ y \sqsubseteq_Y y' & \text{(Counit)}
    \end{align*} 
  \end{enumerate}

\label{thm:map-kohaus-pri}
  Let $(X,\sqsubseteq_X)$ and $(Y,\sqsubseteq_Y)$ be Priestley preorders. There is a bijection between
  \begin{enumerate}
    \item arrows $(L \dashv R):(X,\sqsubseteq_X) \to (Y,\sqsubseteq_Y)$ in $\mathsf{Map}({\mathbb S}\mathsf{pl}_\ge({\mathbb R}\mathsf{el}(\mathsf{Pri})))$, and
    \item continuous monotone maps $f: X/{\sqsubseteq_X} \to Y/{\sqsubseteq_Y}$ in $\mathsf{KOHaus}$.
  \end{enumerate}

\label{rem:map-spl-dl}
  We spell out the conditions on an arrow $L : (A,\prec) \to (A',\prec')$ in $\mathsf{Map}({\mathbb S}\mathsf{pl}_\le({\mathbb R}\mathsf{el}(\mathsf{DL})))$. 
  \begin{enumerate}
    \item \textbf{$L$ is a weakening relation:} for all $a,a' \in A$ and $b,b' \in A'$,
    \[
      a' \prec a \ \wedge \ a \, L \, b \ \wedge \ b \prec' b' \ \Rightarrow \ a' \, L \, b'.
    \]
    \item \textbf{$L$ is a $\mathsf{DL}$-relation:} $L$ can be tabulated in $\mathsf{DL}$ and is compatible with the lattice structure (see Section~\ref{sec:dedekind-cuts}).
    \item \textbf{$L$ is a proximity relation:}
    \[
      {\prec} \mathrel{;} L \mathrel{;} {\prec'} \,=\, L.
    \]
    \item \textbf{$L$ has a right adjoint} $R \subseteq A' \times A$ satisfying ${\prec'} \mathrel{;} R \mathrel{;} {\prec} \,=\, R$ and the adjunction laws: for all $a,a' \in A$ and $b,b' \in A'$,
    \begin{align*}
      a \prec a' \ &\Rightarrow \ \exists b \in A'.\, a \, L \, b \ \wedge \ b \, R \, a' & \text{(Unit)}\\
      \exists a \in A.\, b \, R \, a \, L \, b' \ &\Rightarrow \ b \prec' b' & \text{(Counit)}
    \end{align*}
  \end{enumerate}

\label{rem:kohaus-prox-quasi-inverse}
  Under the equivalence, a compact ordered space $X$ corresponds to its proximity lattice $A_X$ (Definition~\ref{def:kohaus-proximity-lattice}) and $f:X\to Y$ to the rounded companion ${\prec_Y}\mathrel{;}(f^*)_\diamond\mathrel{;}{\prec_X}$ of the proximity morphism $f^*$ (Proposition~\ref{prop:kohaus-to-prox}).
  In particular, every proximity lattice is relationally isomorphic to the strong proximity lattice $A_X$ of its dual compact ordered space $X$.

\label{cor:round-filters-strongification}
The lattice of round filters (dually, round ideals) of a proximity lattice $A$ is isomorphic to the lattice of round filters (dually, round ideals) of $A^*$.
In particular, the dual compact ordered spaces of $A$ and $A^*$ are isomorphic.
